def once(n): return ' Sólo puedes usar este efecto de "%s" una vez por turno.' % n
def one(n): return ' Sólo puedes usar 1 efecto de "%s" por turno, y sólo una vez ese turno.' % n
DR = '"Dragon Ruler"'
def big(attr, n, mid):
    return ('Si esta carta está en tu mano o Cementerio: puedes desterrar un total de 2 monstruos de %s y/o de Tipo Dragón de tu mano y/o Cementerio, excepto esta carta; Invoca esta carta de Modo Especial. Durante la End Phase de tu adversario, si esta carta fue Invocada de Modo Especial: devuélvela a la mano. ' % attr) + mid + (' Si esta carta es desterrada: puedes añadir a tu mano 1 monstruo de Tipo Dragón de %s de tu Deck.' % attr) + one(n)
def baby(attr, big_n, n):
    return ('Puedes descartar esta carta Y 1 monstruo de Tipo Dragón o de %s; Invoca de Modo Especial 1 "%s" de tu Deck. No puede atacar este turno.' % (attr, big_n)) + once(n)
ES = {
"Chasma, Dragon Ruler of Auroras": '2 monstruos de Tipo Dragón de Nivel 7\n(Efecto Rápido): puedes mandar al Cementerio 1 monstruo ' + DR + ' de Nivel 7 de tu Deck y desacoplar 1 material de esta carta; este efecto pasa a ser el efecto de ese monstruo mandado que se descarta a sí mismo para activarse. Si esta carta es destruida en batalla, o si esta carta en posesión de su propietario es destruida por un efecto de carta del adversario: puedes Invocar de Modo Especial 1 monstruo ' + DR + ' de Nivel 7 de tu Cementerio o de entre tus cartas desterradas. Sólo puedes usar cada efecto de "Chasma, Dragon Ruler of Auroras" una vez por turno.',
"Tidal, Dragon Ruler of Waterfalls": big('AGUA', "Tidal, Dragon Ruler of Waterfalls", 'Puedes descartar al Cementerio esta carta y 1 monstruo de AGUA; manda al Cementerio 1 monstruo de tu Deck.'),
"Stream, Dragon Ruler of Droplets": baby('AGUA', "Tidal, Dragon Ruler of Waterfalls", "Stream, Dragon Ruler of Droplets"),
"Eclipse, Dragon Ruler of Catastrophes": '2 monstruos de Tipo Dragón de Nivel 7\nSi esta carta es Invocada por Xyz: puedes seleccionar 1 monstruo ' + DR + ' de Nivel 4 o menor en tu Cementerio o entre tus cartas desterradas; Invoca de Modo Especial desde tu Deck o de entre tus cartas desterradas 1 monstruo ' + DR + ' de Nivel/Rango 7 que aparezca mencionado en ese monstruo seleccionado y, después, baraja el monstruo seleccionado en el Deck. Cuando tu adversario active una Carta o efecto de Mágica/Trampa (Efecto Rápido): puedes desacoplar 2 materiales de esta carta; niega la activación y, si lo haces, destierra esa carta. Sólo puedes usar cada efecto de "Eclipse, Dragon Ruler of Catastrophes" una vez por turno.',
"Burner, Dragon Ruler of Sparks": 'Puedes descartar esta carta y 1 monstruo de Tipo Dragón o de FUEGO; Invoca de Modo Especial 1 "Blaster, Dragon Ruler of Infernos" de tu Deck, pero no puede atacar este turno.' + once("Burner, Dragon Ruler of Sparks"),
"Blaster, Dragon Ruler of Infernos": big('FUEGO', "Blaster, Dragon Ruler of Infernos", 'Puedes descartar al Cementerio esta carta y 1 monstruo de FUEGO y, después, seleccionar 1 carta en el Campo; destruye ese objetivo.').replace('si esta carta fue Invocada de Modo Especial: devuélvela', 'si controlas esta carta Invocada de Modo Especial: devuélvela'),
"Spectral, Dragon Ruler of Flickers": 'Puedes descartar esta carta y 1 monstruo de Tipo Dragón o de LUZ; añade a tu mano 2 monstruos ' + DR + ' de tu Deck, excepto "Spectral, Dragon Ruler of Flickers". Puedes desterrar de tu Cementerio esta carta y 1 monstruo de Tipo Dragón o de LUZ y, después, seleccionar 1 "Chasma, Dragon Ruler of Auroras" en tu Cementerio; Invócalo de Modo Especial.' + one("Spectral, Dragon Ruler of Flickers"),
"Disaster, Dragon Ruler of All Apocalypses": '2 monstruos de Rango 7\nSi esta carta es Invocada por Xyz: puedes seleccionar hasta 4 monstruos ' + DR + ' de Nivel 7 en tu Cementerio y/o entre tus cartas desterradas; acóplalos a esta carta y, después, puedes desterrar todos los monstruos del Campo y del Cementerio de tu adversario con el mismo Atributo que los materiales de esta carta.' + once("Disaster, Dragon Ruler of All Apocalypses") + ' Mientras esta carta tenga como material monstruos ' + DR + ' de LUZ, OSCURIDAD, TIERRA, AGUA, FUEGO y VIENTO, gana 4600 ATK/DEF; además, no es afectada por los efectos de otras cartas.',
"Lightning, Dragon Ruler of Drafts": 'Puedes descartar esta carta y 1 monstruo de Tipo Dragón o de VIENTO; Invoca de Modo Especial 1 "Tempest, Dragon Ruler of Storms" de tu Deck, pero no puede atacar este turno.' + once("Lightning, Dragon Ruler of Drafts"),
"Redox, Dragon Ruler of Boulders": big('TIERRA', "Redox, Dragon Ruler of Boulders", 'Puedes descartar al Cementerio esta carta y 1 monstruo de TIERRA y, después, seleccionar 1 monstruo en tu Cementerio; Invoca de Modo Especial ese objetivo.'),
"Reactan, Dragon Ruler of Pebbles": baby('TIERRA', "Redox, Dragon Ruler of Boulders", "Reactan, Dragon Ruler of Pebbles"),
"Nebulus, Dragon Ruler of Mishaps": 'Puedes descartar esta carta y 1 monstruo de Tipo Dragón o de OSCURIDAD y, después, seleccionar 2 de tus monstruos ' + DR + ' desterrados con Atributos diferentes, excepto "Nebulus, Dragon Ruler of Mishaps"; Invócalos de Modo Especial, pero no pueden atacar este turno. Puedes desterrar de tu Cementerio esta carta y 1 monstruo de Tipo Dragón o de OSCURIDAD y, después, seleccionar 1 "Eclipse, Dragon Ruler of Catastrophes" en tu Cementerio; Invócalo de Modo Especial.' + one("Nebulus, Dragon Ruler of Mishaps"),
}
